# Space optimized version (1D array)
def unique_paths_space_opt(m, n):
    """Count paths with O(n) space."""
    dp = [1] * n
    for i in range(1, m):
        for j in range(1, n):
            dp[j] += dp[j-1]
    return dp[n-1]
# Using combinatorics: C(m+n-2, m-1)
def unique_paths_math(m, n):
    """Count paths using combinatorial formula."""
    from math import comb
    return comb(m + n - 2, m - 1)
# With obstacles
def unique_paths_with_obstacles(grid):
    """Count paths with obstacles (1=obstacle, 0=empty)."""
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    # Initialize first cell
    dp[0][0] = 0 if grid[0][0] == 1 else 1
    # Initialize first column
    for i in range(1, m):
        dp[i][0] = dp[i-1][0] if grid[i][0] == 0 else 0
    # Initialize first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] if grid[0][j] == 0 else 0
    # Fill DP table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0
    return dp[m-1][n-1]
